def jaro(s1,s2):
    if s1==s2: return 1.0
    l1,l2=len(s1),len(s2)
    if l1==0 or l2==0: return 0.0
    md=max(l1,l2)//2-1
    s1m=[False]*l1; s2m=[False]*l2; m=0
    for i in range(l1):
        s=max(0,i-md); e=min(i+md+1,l2)
        for j in range(s,e):
            if not s2m[j] and s1[i]==s2[j]:
