import math
def fwd_rounded(r,g,b):
    def inv(c):
        c=c/255
        return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
    rl,gl,bl=inv(r),inv(g),inv(b)
    x=rl*0.4124+gl*0.3576+bl*0.1805
    y=rl*0.2126+gl*0.7152+bl*0.0722
    z=rl*0.0193+gl*0.1192+bl*0.9505
    xn,yn,zn=0.95047,1.0,1.08883
    def f(t):
        d=6/29
        return t**(1/3) if t>d**3 else t/(3*d**2)+4/29
    return (116*f(y/yn)-16, 500*(f(x/xn)-f(y/yn)), 200*(f(y/yn)-f(z/zn)))
def rev_precise(L,a,b_):
    xn,yn,zn=0.95047,1.0,1.08883
    fy=(L+16)/116; fx=fy+a/500; fz=fy-b_/200
    d=6/29
    def finv(t):
        return t**3 if t>d else 3*d**2*(t-4/29)
    x=xn*finv(fx); y=yn*finv(fy); z=zn*finv(fz)
    rl=x*3.2404542+y*-1.5371385+z*-0.4985314
    gl=x*-0.9692660+y*1.8760108+z*0.0415560
    bl=x*0.0556434+y*-0.2040259+z*1.0572252
    def comp(c):
        return c*12.92 if c<=0.0031308 else 1.055*(c**(1/2.4))-0.055
    r=comp(rl); g=comp(gl); b=comp(bl)
    def q(v):
        v=max(0,min(1,v))
        return int(math.floor(v*255+0.5))
    return (q(r),q(g),q(b))
red=fwd_rounded(255,0,0)
blue=fwd_rounded(0,0,255)
